/bin/zsh -lc "python3 -c 'import json,itertools
with open(\"input.json\") as f:
    d=json.load(f)
def reach(s,t,removed=frozenset()):
    seen={s}
    todo=[s]
    while todo:
        u=todo.pop()
        if u==t:
            return True
        for e in d[\"edges\"]:
            if e[\"id\"] not in removed and e[\"source\"]==u and e[\"target\"] not in seen:
                seen.add(e[\"target\"])
                todo.append(e[\"target\"])
    return False
reachable=[]
authorized=[]
for p in sorted(d[\"probes\"],key=lambda x:x[\"id\"]):
    r=reach(p[\"source\"],p[\"target\"])
    if r:
        reachable.append(p[\"id\"])
    if r and p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and d[\"now\"]<p[\"expires\"] and p[\"key\"] not in d[\"revoked_keys\"]:
        authorized.append(p[\"id\"])
removable=sorted((e for e in d[\"edges\"] if e[\"removable\"]),key=lambda e:e[\"id\"])
best=None
checked=0
feasible=0
for bits in itertools.product((False,True),repeat=len(removable)):
    removed=[e for e,b in zip(removable,bits) if b]
    ids=[e[\"id\"] for e in removed]
    checked+=1
    if any(reach(s,t,set(ids)) for s,t in d[\"forbidden\"]):
        continue
    if not all(reach(s,t,set(ids)) for s,t in d[\"required\"]):
        continue
    feasible+=1
    candidate=(sum(e[\"cost\"] for e in removed),len(ids),ids)
    if best is None or candidate<best:
        best=candidate
print(json.dumps({\"reachable_probes\":reachable,\"authorized_probes\":authorized,\"repair_edges\":best[2],\"repair_cost\":best[0]},separators=(\",\",\":\")))
print(json.dumps({\"subsets_checked\":checked,\"feasible_subsets\":feasible,\"objective\":best}))'"

